import { ElectricLab } from './ui/electricLab';

const host = document.querySelector<HTMLElement>('[data-electric-lab]');
if (!host) throw new Error('Electric Lab page is missing its workbench.');
export let electricLab = new ElectricLab(host);
const lifecycle = new AbortController();

window.addEventListener('pagehide', () => electricLab.dispose(), { signal: lifecycle.signal });
window.addEventListener('pageshow', event => {
  if (event.persisted) electricLab = new ElectricLab(host);
}, { signal: lifecycle.signal });
if (import.meta.hot) import.meta.hot.dispose(() => {
  lifecycle.abort();
  electricLab.dispose();
});
