import './electricLab.css';
import { createAcousticBus, playAcousticString, stopAcousticSources, type AcousticBus } from '../audio/engine';
import { loadGuitarBank } from '../audio/guitarSamples';
import {
  ELECTRIC_CHORDS, ELECTRIC_FINISHES, ELECTRIC_MODEL, ELECTRIC_PARTS, electricNotes, electricSequence, isElectricFinish,
  type ElectricChordId, type ElectricFinishId, type ElectricPartId, type ElectricPattern, type ElectricView,
} from '../theory/electricLab';
import type { ElectricLab3D } from './electricLab3d';

const MODEL_TIMEOUT = 20000;

export class ElectricLab {
  private events = new AbortController();
  private motion = matchMedia('(prefers-reduced-motion: reduce)');
  private scene: ElectricLab3D | null = null;
  private loadingScene: ElectricLab3D | null = null;
  private modelRequest: AbortController | null = null;
  private modelGeneration = 0;
  private disposed = false;
  private chord: ElectricChordId = 'open';
  private finish: ElectricFinishId = 'cherry';
  private selected: ElectricPartId | null = null;
  private context: AudioContext | null = null;
  private bus: AcousticBus | null = null;
  private audioGeneration = 0;
  private audioLoading = false;
  private timers = new Set<ReturnType<typeof setTimeout>>();
  private volume = .6;

  constructor(private root: HTMLElement) {
    const signal = this.events.signal;
    this.find<HTMLSelectElement>('[data-el-chord]').value = this.chord;
    this.find<HTMLSelectElement>('[data-el-finish]').value = this.finish;
    this.volume = Number(this.find<HTMLInputElement>('[data-el-volume]').value) / 100;
    this.root.addEventListener('click', this.click, { signal });
    this.root.addEventListener('keydown', event => {
      if (!/^[1-6]$/.test(event.key) || event.repeat || event.ctrlKey || event.metaKey || event.altKey ||
        (event.target as Element).matches('input, select, textarea')) return;
      event.preventDefault(); void this.play(Number(event.key) - 1);
    }, { signal });
    this.find<HTMLSelectElement>('[data-el-chord]').addEventListener('change', event => {
      const chord = (event.target as HTMLSelectElement).value;
      if (!Object.hasOwn(ELECTRIC_CHORDS, chord)) return;
      this.stopAudio();
      this.chord = chord as ElectricChordId;
      this.scene?.setChord(this.chord);
      this.renderStrings();
      this.audioStatus(`${ELECTRIC_CHORDS[this.chord].name} selected. Choose Play or an individual string.`);
    }, { signal });
    this.find<HTMLSelectElement>('[data-el-view]').addEventListener('change', event => {
      const view = (event.target as HTMLSelectElement).value as ElectricView;
      if (!['three-quarter', 'front', 'back', 'side'].includes(view) || !this.scene) return;
      this.select(null, false); this.scene.view(view);
      this.viewStatus(`Whole guitar · ${view} view.`);
    }, { signal });
    this.find<HTMLSelectElement>('[data-el-finish]').addEventListener('change', event => {
      const control = event.target as HTMLSelectElement;
      if (!isElectricFinish(control.value)) {
        control.value = this.finish;
        this.viewStatus('Choose one of the available guitar finishes.');
        return;
      }
      this.finish = control.value;
      this.scene?.setFinish(this.finish);
      this.finishLabel();
      this.viewStatus(`${ELECTRIC_FINISHES[this.finish].name} selected. ${this.finish === 'neutral' ? 'Saved source tint.' : 'Custom Lab colour; original geometry unchanged.'}`);
    }, { signal });
    this.find<HTMLInputElement>('[data-el-wireframe]').addEventListener('change', event => {
      this.scene?.setWireframe((event.target as HTMLInputElement).checked);
    }, { signal });
    this.find<HTMLInputElement>('[data-el-guides]').addEventListener('change', event => {
      this.scene?.setGuides((event.target as HTMLInputElement).checked);
    }, { signal });
    this.find<HTMLInputElement>('[data-el-volume]').addEventListener('input', event => {
      this.volume = Number((event.target as HTMLInputElement).value) / 100;
      this.find('[data-el-volume-value]').textContent = `${Math.round(this.volume * 100)}%`;
      if (this.bus && this.context) this.bus.masterOut.gain.setTargetAtTime(this.volume, this.context.currentTime, .015);
    }, { signal });
    this.motion.addEventListener('change', () => this.scene?.setReducedMotion(this.motion.matches), { signal });
    document.addEventListener('visibilitychange', () => {
      this.scene?.setActive(!document.hidden);
      if (document.hidden) {
        this.stopAudio();
        if (this.context?.state === 'running') void this.context.suspend().catch(() => {});
      }
    }, { signal });
    this.renderStrings();
    this.select(null, false);
    void this.loadModel();
  }

  private find<T extends HTMLElement = HTMLElement>(selector: string): T {
    const element = this.root.querySelector<T>(selector);
    if (!element) throw new Error(`Electric Lab control missing: ${selector}`);
    return element;
  }

  private click = (event: MouseEvent): void => {
    const button = (event.target as Element).closest<HTMLButtonElement>('button');
    if (!button || button.disabled || !this.root.contains(button)) return;
    if (button.hasAttribute('data-el-retry')) { void this.loadModel(); return; }
    if (button.hasAttribute('data-el-play')) { void this.play(); return; }
    if (button.hasAttribute('data-el-stop')) { this.stopAudio(); return; }
    if (button.hasAttribute('data-el-string')) { void this.play(Number(button.dataset.elString)); return; }
    if (button.dataset.elPart && Object.hasOwn(ELECTRIC_PARTS, button.dataset.elPart)) {
      this.select(button.dataset.elPart as ElectricPartId); return;
    }
    if (button.hasAttribute('data-el-whole') || button.dataset.elCamera === 'reset') {
      this.select(null, false); this.scene?.reset();
      this.find<HTMLSelectElement>('[data-el-view]').value = 'three-quarter';
      this.viewStatus(this.scene ? 'Whole guitar · three-quarter view.' : 'Whole guitar. 3D is unavailable; the part notes and sound controls still work.');
      return;
    }
    if (button.dataset.elCamera) this.scene?.cameraAction(button.dataset.elCamera);
  };

  private modelState(state: 'loading' | 'ready' | 'error' | 'unavailable', message: string): void {
    this.root.dataset.modelState = state;
    this.find('[data-el-stage]').setAttribute('aria-busy', String(state === 'loading'));
    this.find('[data-el-model-status]').textContent = message;
    this.find('[data-el-load-panel]').hidden = state === 'ready';
    this.find('[data-el-fallback]').hidden = state === 'ready';
    this.find<HTMLButtonElement>('[data-el-retry]').hidden = state === 'ready' || state === 'loading';
    this.root.querySelectorAll<HTMLButtonElement | HTMLInputElement | HTMLSelectElement>('[data-el-camera], [data-el-view], [data-el-wireframe], [data-el-guides], [data-el-finish]')
      .forEach(control => { control.disabled = state !== 'ready'; });
    this.finishLabel();
  }

  private finishLabel(): void {
    this.find('[data-el-stage-label]').textContent = this.root.dataset.modelState !== 'ready'
      ? 'Recovered geometry · neutral reference'
      : `${ELECTRIC_FINISHES[this.finish].name} · ${this.finish === 'neutral' ? 'saved source tint' : 'custom Lab finish'}`;
  }

  private async loadModel(): Promise<void> {
    if (this.disposed) return;
    const generation = ++this.modelGeneration;
    this.modelRequest?.abort();
    this.scene?.dispose(); this.scene = null;
    this.loadingScene?.dispose(); this.loadingScene = null;
    const controller = new AbortController();
    this.modelRequest = controller;
    const timer = setTimeout(() => controller.abort(), MODEL_TIMEOUT);
    this.modelState('loading', 'Loading the recovered guitar… Part notes and recorded playback are available while it loads.');
    let candidate: ElectricLab3D | null = null;
    const current = () => !this.disposed && generation === this.modelGeneration;
    try {
      const [{ ElectricLab3D }, response] = await Promise.all([
        import('./electricLab3d'),
        fetch(`${import.meta.env.BASE_URL}${ELECTRIC_MODEL.url}`, { signal: controller.signal }),
      ]);
      if (!current()) return;
      if (!response.ok) throw new Error(`Model request failed (${response.status}).`);
      const bytes = await response.arrayBuffer();
      if (!current()) return;
      if (bytes.byteLength !== ELECTRIC_MODEL.bytes) throw new Error('The recovered model is incomplete.');
      candidate = new ElectricLab3D(this.find('[data-el-render]'), {
        reducedMotion: this.motion.matches,
        onPart: part => this.select(part),
        onString: index => { void this.play(index); },
        onCamera: () => this.viewStatus('Free view. Use Reset view to show the whole guitar.'),
        onReset: () => {
          this.select(null, false);
          this.find<HTMLSelectElement>('[data-el-view]').value = 'three-quarter';
          this.viewStatus('Whole guitar · three-quarter view.');
        },
        onUnavailable: () => {
          if (!current()) return;
          this.modelGeneration++;
          this.scene?.dispose(); this.scene = null;
          this.loadingScene?.dispose(); this.loadingScene = null;
          this.modelState('unavailable', 'The 3D graphics connection was lost. Retry 3D; part notes and recorded playback still work.');
        },
      });
      this.loadingScene = candidate;
      await candidate.load(bytes);
      if (!current()) { candidate.dispose(); return; }
      this.scene = candidate; this.loadingScene = null;
      this.scene.setFinish(this.finish);
      this.scene.setChord(this.chord);
      this.scene.setGuides(this.find<HTMLInputElement>('[data-el-guides]').checked);
      this.scene.setWireframe(this.find<HTMLInputElement>('[data-el-wireframe]').checked);
      if (this.selected) this.scene.inspect(this.selected);
      this.scene.setActive(!document.hidden);
      this.modelState('ready', 'Recovered geometry ready. Custom Lab finishes are available; the original runtime finish is not yet verified.');
    } catch (error) {
      candidate?.dispose();
      if (!current()) return;
      this.loadingScene = null;
      const noWebGL = error instanceof Error && error.message.includes('WebGL');
      this.modelState(noWebGL ? 'unavailable' : 'error', noWebGL
        ? '3D needs WebGL, which is unavailable in this browser. Enable hardware graphics or try another browser, then Retry 3D. Part notes and recorded playback still work.'
        : 'The recovered model could not load. Check the local connection and Retry 3D. Part notes and recorded playback still work.');
    } finally {
      clearTimeout(timer);
      if (current()) this.modelRequest = null;
    }
  }

  private select(part: ElectricPartId | null, focus = true): void {
    this.selected = part;
    this.root.querySelectorAll<HTMLButtonElement>('[data-el-part]').forEach(button => {
      button.setAttribute('aria-pressed', String(button.dataset.elPart === part));
    });
    this.find('[data-el-part-title]').textContent = part ? ELECTRIC_PARTS[part].name : 'Recovered geometry';
    this.find('[data-el-part-info]').textContent = part ? ELECTRIC_PARTS[part].info
      : 'Choose an area to bring it closer and learn what it does. The original mesh stays intact; these are inspection guides, not independently removable parts.';
    if (focus) {
      this.scene?.inspect(part);
      this.find<HTMLSelectElement>('[data-el-view]').value = 'three-quarter';
      this.viewStatus(part ? `${ELECTRIC_PARTS[part].name}${this.scene ? ' · inspection view.' : ' · notes only; 3D is unavailable.'}` : 'Whole guitar.');
    }
  }

  private viewStatus(message: string): void { this.find('[data-el-view-status]').textContent = message; }
  private audioStatus(message: string): void { this.find('[data-el-audio-status]').textContent = message; }

  private renderStrings(): void {
    const notes = electricNotes(this.chord);
    this.root.querySelectorAll<HTMLButtonElement>('[data-el-string]').forEach(button => {
      const index = Number(button.dataset.elString);
      const note = notes.find(item => item.stringIndex === index);
      button.querySelector('strong')!.textContent = note?.name ?? '×';
      button.querySelector('small')!.textContent = note ? note.fret ? `Fret ${note.fret}` : 'Open' : 'Muted';
      button.setAttribute('aria-label', note ? `Play string ${index + 1}, ${note.name}, ${note.fret ? `fret ${note.fret}` : 'open'}`
        : `String ${index + 1}, muted in ${ELECTRIC_CHORDS[this.chord].name}`);
      button.disabled = this.audioLoading || !note;
    });
    const play = this.find<HTMLButtonElement>('[data-el-play]');
    play.disabled = this.audioLoading;
    play.textContent = this.audioLoading ? 'Loading recordings…' : this.chord === 'open' ? 'Play open strings' : `Play ${this.chord}`;
  }

  private later(callback: () => void, delay: number): void {
    const timer = setTimeout(() => { this.timers.delete(timer); callback(); }, delay);
    this.timers.add(timer);
  }

  private async play(onlyString?: number): Promise<void> {
    if (this.disposed || document.hidden || this.audioLoading) return;
    const pattern = this.find<HTMLSelectElement>('[data-el-pattern]').value as ElectricPattern;
    const notes = electricSequence(this.chord, pattern, onlyString);
    if (!notes.length) {
      this.audioStatus(`String ${(onlyString ?? 0) + 1} is muted in ${ELECTRIC_CHORDS[this.chord].name}. Choose another string.`);
      return;
    }
    this.stopAudio(false);
    const generation = this.audioGeneration;
    const current = () => !this.disposed && generation === this.audioGeneration && !document.hidden;
    this.audioLoading = true; this.renderStrings();
    this.find<HTMLButtonElement>('[data-el-stop]').disabled = false;
    this.root.dataset.audioState = 'loading';
    this.audioStatus('Loading the recorded electric guitar… You can stop or change shape while it loads.');
    try {
      // Create/resume synchronously inside the explicit gesture; this page never borrows the main app's audio context.
      const context = this.context ??= new AudioContext();
      await Promise.all([context.resume(), loadGuitarBank(context, 'electric')]);
      if (!current()) return;
      if (context.state !== 'running') throw new Error('Sound is blocked by the browser. Select Play again to retry.');
      this.bus ??= createAcousticBus(context, { bank: 'electric', masterVolume: this.volume, strumStyle: 'down', sampleRate: context.sampleRate });
      const now = context.currentTime + .025;
      for (const note of notes) {
        const source = playAcousticString(context, this.bus, {
          freq: 440 * 2 ** ((note.midi - 69) / 12), stringIndex: note.stringIndex, velocity: .85,
          startTime: now + note.delay, endTime: now + note.delay + 3,
        });
        source.addEventListener('ended', () => {
          if (current() && this.bus?.sources.size === 0) {
            this.find<HTMLButtonElement>('[data-el-stop]').disabled = true;
            this.root.dataset.audioState = 'idle';
            this.audioStatus('Finished. Play another shape or try an individual string.');
          }
        }, { once: true });
        this.later(() => {
          if (!current()) return;
          this.scene?.pulseString(note.stringIndex);
          const button = this.find<HTMLButtonElement>(`[data-el-string="${note.stringIndex}"]`);
          button.dataset.playing = 'true';
          this.later(() => { delete button.dataset.playing; }, 700);
        }, Math.max(0, (now + note.delay - context.currentTime) * 1000));
      }
      this.root.dataset.audioState = 'playing';
      this.audioStatus(onlyString === undefined
        ? `${ELECTRIC_CHORDS[this.chord].name} · ${pattern === 'arpeggio' ? 'arpeggio' : 'down strum'} · ${notes.map(note => note.name).join(', ')}.`
        : `String ${onlyString + 1} · ${notes[0].name} · ${notes[0].fret ? `fret ${notes[0].fret}` : 'open'}.`);
    } catch {
      if (current()) {
        this.stopAudio(false);
        this.root.dataset.audioState = 'error';
        this.audioStatus('Recorded playback is unavailable. Check the local connection or browser sound permission, then select Play or a string to retry.');
      }
    } finally {
      if (current()) { this.audioLoading = false; this.renderStrings(); }
    }
  }

  private stopAudio(announce = true): void {
    this.audioGeneration++;
    const hadAudio = this.audioLoading || !!this.bus?.sources.size;
    this.audioLoading = false;
    this.timers.forEach(timer => clearTimeout(timer)); this.timers.clear();
    if (this.bus && this.context?.state !== 'closed') stopAcousticSources(this.bus);
    this.scene?.stopStrings();
    this.root.querySelectorAll<HTMLElement>('[data-el-string]').forEach(button => { delete button.dataset.playing; });
    this.find<HTMLButtonElement>('[data-el-stop]').disabled = true;
    this.root.dataset.audioState = 'idle';
    this.renderStrings();
    if (announce && hadAudio) this.audioStatus('Sound stopped. Play again whenever you like.');
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.events.abort();
    this.modelGeneration++; this.modelRequest?.abort(); this.modelRequest = null;
    this.scene?.dispose(); this.scene = null;
    this.loadingScene?.dispose(); this.loadingScene = null;
    this.stopAudio(false);
    this.bus?.input.disconnect(); this.bus?.limiter.disconnect(); this.bus?.masterOut.disconnect(); this.bus = null;
    if (this.context && this.context.state !== 'closed') void this.context.close().catch(() => {});
    this.context = null;
    this.root.dataset.modelState = 'disposed';
  }
}
