// Shape indices follow the shared audio engine: high E first, low E last.
export const ELECTRIC_CHORDS = {
  open: { name: 'Open strings', frets: [0, 0, 0, 0, 0, 0] },
  Em: { name: 'E minor', frets: [0, 0, 0, 2, 2, 0] },
  Am: { name: 'A minor', frets: [0, 1, 2, 2, 0, null] },
  D: { name: 'D major', frets: [2, 3, 2, 0, null, null] },
  G: { name: 'G major', frets: [3, 0, 0, 0, 2, 3] },
} as const;
export type ElectricChordId = keyof typeof ELECTRIC_CHORDS;
export const ELECTRIC_NUT_X = -.715;
export const ELECTRIC_BRIDGE_X = -.030;

export function electricNoteName(midi: number): string {
  return `${['C', 'C♯', 'D', 'D♯', 'E', 'F', 'F♯', 'G', 'G♯', 'A', 'A♯', 'B'][midi % 12]}${Math.floor(midi / 12) - 1}`;
}

export function electricNotes(chord: ElectricChordId) {
  return ELECTRIC_CHORDS[chord].frets.flatMap((fret, stringIndex) => fret === null ? [] : [{
    stringIndex, fret, midi: STANDARD_TUNING[stringIndex].midi + fret,
    name: electricNoteName(STANDARD_TUNING[stringIndex].midi + fret),
  }]);
}

export function electricSequence(chord: ElectricChordId, pattern: ElectricPattern, onlyString?: number) {
  return electricNotes(chord).filter(note => onlyString === undefined || note.stringIndex === onlyString)
    .sort((a, b) => b.stringIndex - a.stringIndex)
    .map((note, index) => ({ ...note, delay: index * (pattern === 'arpeggio' ? .110 : .022) }));
}

/** Overlay coordinates in the unchanged GLB's local space, not new source vertices. */
export function electricStringPoint(stringIndex: number, fret: number): [number, number, number] {
  const amount = 1 - 2 ** (-Math.max(0, fret) / 12);
  return [
    ELECTRIC_NUT_X + (ELECTRIC_BRIDGE_X - ELECTRIC_NUT_X) * amount,
    -.0285 - .010 * amount,
    (.019 + .007 * amount) * (1 - stringIndex * 2 / 5),
  ];
}

export function electricPartAt(x: number, z: number): ElectricPartId {
  if (x < -.725) return 'headstock';
  if (x < -.225 && Math.abs(z) < .05) return 'neck';
  if (x > -.015 && z > .055) return 'controls';
  if (x > -.205 && x < -.055 && Math.abs(z) < .052) return 'pickups';
  if (x >= -.055 && x < .055 && Math.abs(z) < .06) return 'bridge';
  return 'body';
}
